'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\r\n', [['']]],
  ['\r\n\r\n\n\r', [[''], [''], [''], ['']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  [',', [['', '']]],
  ['a,,b,', [['a', '', 'b', '']]],
  ['""', [['']]],
  ['""""', [['"']]],
  ['"a,b","say ""hi"""\r\n', [['a,b', 'say "hi"']]],
  ['ab"cd,"x\r\ny\rz\n",end', [['ab"cd', 'x\r\ny\rz\n', 'end']]],
  ['\uFEFFa,\uFEFFb\n\uFEFF', [['a', '\uFEFFb'], ['\uFEFF']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]],
  ['a\uD83D\uDE00,"\uD83D\uDE00"', [['a\uD83D\uDE00', '\uD83D\uDE00']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb\t', [['a', 'b', '']], { delimiter: '\t' }],
  ['a\uD800b', [['a', 'b']], { delimiter: '\uD800' }],
  ['a\0b', [['a', 'b']], { delimiter: '\0' }],
];

test('grammar is invariant across every two-way split and code-unit chunks', () => {
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser(options);
      const actual = parser.push('');
      actual.push(...parser.push(text.slice(0, split)));
      actual.push(...parser.push(''));
      actual.push(...parser.push(text.slice(split)));
      actual.push(...parser.end());
      assert.deepEqual(actual, expected, JSON.stringify({ text, split }));
      assert.deepEqual(parser.end(), []);
    }
    const parser = createParser(options);
    const actual = [];
    for (let index = 0; index < text.length; index++) {
      actual.push(...parser.push(''), ...parser.push(text[index]));
    }
    actual.push(...parser.end());
    assert.deepEqual(actual, expected);
  }
});

test('records emit immediately, without repeats or trailing phantom rows', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push('a\r'), [['a']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\nb\n\r'), [['b'], ['']]);
  assert.deepEqual(parser.push('\n"c\r'), []);
  assert.deepEqual(parser.push('\nd"\r'), [['c\r\nd']]);
  assert.deepEqual(parser.push('\nlast,'), []);
  assert.deepEqual(parser.end(), [['last', '']]);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  assert.throws(() => parser.push('more'), Error);
});

test('validation occurs at creation and push; states are independent', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 0, {}, []]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
    assert.throws(() => parse('', { delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const first = createParser();
  const second = createParser();
  for (const chunk of [undefined, null, 1, {}, [], Buffer.from('a'), new String('a')]) {
    assert.throws(() => first.push(chunk), TypeError);
    assert.throws(() => parse(chunk), TypeError);
  }
  assert.deepEqual(first.push('"left'), []);
  assert.deepEqual(second.push('right\n'), [['right']]);
  assert.deepEqual(first.push(' side"\n'), [['left side']]);
  assert.deepEqual(first.end(), []);
  assert.deepEqual(second.end(), []);
});

test('syntax errors report physical lines across all chunk boundaries', () => {
  const errors = [
    ['"a"x', 1, false],
    ['"a" ', 1, false],
    ['ok\r\n"a"x', 2, false],
    ['"a\r\nb\rc\nd"!', 4, false],
    ['\n\r\n\r"a"x', 4, false],
    ['"', 1, true],
    ['"a\r\nb\rc\n', 4, true],
    ['"a\r\n', 2, true],
    ['"a\r', 2, true],
    ['"a""', 1, true],
  ];
  for (const [text, line, atEnd] of errors) {
    const matches = error => error instanceof SyntaxError &&
      new RegExp(`\\bline ${line}\\b`).test(error.message);
    assert.throws(() => parse(text), matches);
    for (let split = 0; split <= text.length; split++) {
      const parser = createParser();
      if (atEnd) {
        parser.push(text.slice(0, split));
        parser.push('');
        parser.push(text.slice(split));
        assert.throws(() => parser.end(), matches);
      } else {
        assert.throws(() => {
          parser.push(text.slice(0, split));
          parser.push('');
          parser.push(text.slice(split));
        }, matches);
      }
    }
  }
});

test('header integration preserves duplicates, special keys and padding', () => {
  const text = 'x,x,x_2,x,__proto__,constructor,toString,\n1,2,3,4,5,6,7,8,extra\nshort\n';
  const objects = parse(text, { header: true });
  assert.deepEqual(Object.keys(objects[0]), [
    'x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', '',
  ]);
  assert.deepEqual(Object.values(objects[0]), ['1', '2', '3', '4', '5', '6', '7', '8']);
  assert.deepEqual(Object.values(objects[1]), ['short', '', '', '', '', '', '', '']);
  assert.equal(Object.getPrototypeOf(objects[0]), Object.prototype);
  for (const key of Object.keys(objects[0])) {
    const descriptor = Object.getOwnPropertyDescriptor(objects[0], key);
    assert.equal(descriptor.enumerable, true);
    assert.equal(descriptor.writable, true);
    assert.equal(descriptor.configurable, true);
  }
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('a,b', { header: true }), []);
  assert.deepEqual(parse('a,b\n1,2', { header: false }), [['a', 'b'], ['1', '2']]);
  const records = Object.freeze([Object.freeze(['v']), Object.freeze(['w', 'extra'])]);
  const header = Object.freeze(['__proto__', 'x', 'x']);
  const options = Object.freeze({ header });
  assert.deepEqual(toObjects(records, options).map(Object.values), [['v', '', ''], ['w', 'extra', '']]);
  assert.deepEqual(records, [['v'], ['w', 'extra']]);
  assert.deepEqual(header, ['__proto__', 'x', 'x']);
  assert.deepEqual(toObjects(records, { header: [] }), [{}, {}]);
  const implicit = Object.freeze([Object.freeze(['x', 'x']), Object.freeze(['1'])]);
  assert.deepEqual(toObjects(implicit), [{ x: '1', x_2: '' }]);
  assert.deepEqual(implicit, [['x', 'x'], ['1']]);
});
